{"command":"cd /work/workspace && python3 - <<'EOF'
import csv, json
from decimal import Decimal
from collections import defaultdict
def M(v):
    v = (v or '').strip().replace(',', '')
    if v in ('', '-'):
        return Decimal(0)
    neg = v.startswith('(') and v.endswith(')')
    d = Decimal(v.strip('()'))
    return -d if neg else d

gl = list(csv.DictReader(open('documents/general_ledger_2026-03.csv')))
feb = {}
for r in csv.DictReader(open('documents/trial_balance_2026-02-28.csv')):
    if r['account']:
        feb[r['account']] = (M(r['debit']), M(r['credit']))
glmar = [r for r in gl if r['date'].startswith('2026-03')]
glfeb = [r for r in gl if not r['date'].startswith('2026-03')]
moved = {r['account'] for r in glfeb}

net = defaultdict(lambda: [Decimal(0), Decimal(0)])
for r in glmar:
    net[r['account']][0] += M(r['debit']); net[r['account']][1] += M(r['credit'])
for acct in sorted(set(net) - moved):
    d, c = feb.get(acct, (Decimal(0), Decimal(0)))
    if (d + net[acct][0]) < 0 or (c + net[acct][1]) < 0:
        print("!! would go negative:", acct, d + net[acct][0], c + net[acct][1])

adj = {"1000": [Decimal("4312.00"), Decimal("0")],
       "1300": [Decimal("2338.00"), Decimal("0")],
       "2000": [Decimal("0"), Decimal("4860.00")],
       "2100": [Decimal("0"), Decimal("4312.00")],
       "3200": [Decimal("212.00"), Decimal("0")],
       "4000": [Decimal("0"), Decimal("1500.00")],
       "4420": [Decimal("0"), Decimal("1500.00")],
       "5000": [Decimal("0"), Decimal("4860.00")],
       "6500": [Decimal("35.00"), Decimal("0")]}
out, td, tc = {}, Decimal(0), Decimal(0)
for acct in sorted(set(feb) | set(net) | set(adj)):
    d = feb.get(acct, (Decimal(0), Decimal(0)))[0] + net[acct][0] + adj.get(acct, [Decimal(0), Decimal(0)])[0]
    c = feb.get(acct, (Decimal(0), Decimal(0)))[1] + net[acct][1] + adj.get(acct, [Decimal(0), Decimal(0)])[1]
    td += d; tc += c
    if d != c:
        out[acct] = str(d if d >= c else Decimal(0))
json.dump({"as_of": "2026-03-31", "accounts": out}, open('deliverable/trial_balance_2026-03-31.json', 'w'), indent=2)
print("balanced:", td == tc, float(td), float(tc))
for a in ["1000", "1100", "1300", "2000", "2050", "2100", "4000", "4420", "5000", "6500"]:
    print(a, out.get(a))
ni = sum(M(v) for k, v in out.items() if k[0] in '45') - sum(M(v) for k, v in out.items() if k[0] in '6789')
print("March net income change in equity:", float(ni))
EOF"}

