import csv, json
from collections import defaultdict
def key(r): return r["account"].strip()
feb={}
for r in csv.DictReader(open("documents/trial_balance_2026-02-28.csv")):
    d=float(r["debit"] or 0); c=float(r["credit"] or 0)
    if d or c: feb[key(r)]=round(d-c,2)
gln=defaultdict(float); glc=defaultdict(float); febrows=[]
for r in csv.DictReader(open("documents/general_ledger_2026-03.csv")):
    if not r["date"].strip().startswith("2026-03"):
        febrows.append((r["date"],r["ref"],key(r),r["debit"],r["credit"])); continue
    gln[key(r)]+=float(r["debit"] or 0); glc[key(r)]+=float(r["credit"] or 0)
aje=defaultdict(float)
for e in json.load(open("deliverable/adjusting_entries.json")):
    for l in e["lines"]:
        aje[str(l["account"])]+=l["debit"]-l["credit"]
tb=json.load(open("deliverable/trial_balance_2026-03-31.json"))["accounts"]
bad=[]
for k in sorted(set(feb)|set(gln)|set(aje)|set(tb)):
    expected=round(feb.get(k,0)+gln.get(k,0)-glc.get(k,0)+aje.get(k,0),2)
    actual=round(tb.get(k,{}).get("debit",0)-tb.get(k,{}).get("credit",0),2)
    if abs(expected-actual)>0.004: bad.append((k,expected,actual))
print("GL rows not dated March:", febrows)
print("roll-forward mismatches:", bad if bad else "NONE")
print("file TB: Dr",round(sum(v['debit'] for v in tb.values()),2),"Cr",round(sum(v['credit'] for v in tb.values()),2))
print("feb-only accts kept:", [k for k in feb if k not in set(gln)|set(aje)])
EOF

